/*
 * World geometry for the Live tab's map, as plain SVG path data.
 *
 * Generated once from `world-atlas` (Natural Earth 110m, public domain) and
 * committed as source, deliberately. The alternative is shipping a mapping
 * library plus a topology asset into the admin bundle and re-projecting on
 * every render, to draw a picture that never changes.
 *
 * The projection is plate carree (equirectangular), cropped to 84N..60S, which
 * is why `project()` below is arithmetic rather than a dependency: any
 * lon/lat can be placed on this map without a projection library. Antarctica
 * is dropped — a third of the ink for a place with no visitors.
 *
 * `name` is the Natural Earth name, which is not always what GA4 calls the
 * same country. Reconciling the two is `country-lookup.ts`, not this file.
 *
 * DO NOT hand-edit the path data. To regenerate it from a newer atlas, decode
 * `world-atlas/countries-110m.json` (delta-decoded arcs through the topology's
 * own `transform`), drop Antarctica, project each ring with the `project()`
 * below, round to whole viewBox units and emit relative `l` commands — the
 * rounding and the relative commands are what keep this file at 58 kB rather
 * than 119 kB. Three details are not obvious and were each a visible bug
 * first:
 *
 * - **Split every ring at the antimeridian.** Russia and Fiji are single
 *   rings that leave the right edge and continue on the left; drawn whole,
 *   the seam edge is a horizontal streak across the entire map.
 * - **Take the centroid per split piece, before rounding.** The area centroid
 *   of a wrapping ring is meaningless — Russia's came out at 203E, off the
 *   map, and Fiji's landed in the middle of Africa.
 * - **Do not zero-pad a missing id.** Kosovo, Northern Cyprus and Somaliland
 *   have no ISO code, and padding an empty one gives all three `000`, so
 *   colouring any one of them colours the other two.
 *
 * Natural Earth 110m contains no micro-states at all; those are carried as
 * hand-placed coordinates in `country-lookup.ts`.
 */

export type WorldCountry = {
  /**
   * ISO 3166-1 numeric, zero-padded — or `x-<slug>` for the three disputed
   * territories the standard does not cover (Kosovo, Northern Cyprus,
   * Somaliland), which the atlas ships with no code at all.
   */
  id: string;
  /** Natural Earth English name. GA4's spelling can differ — see `country-lookup.ts`. */
  name: string;
  /** Marker anchor: area centroid of the largest landmass, in viewBox units. */
  x: number;
  y: number;
  /**
   * SVG path data in the viewBox below. Empty for countries too small to
   * survive rounding — they are marker-only, which is how a dashboard would
   * have to show Malta or Singapore at this scale regardless.
   */
  d: string;
};

export const WORLD_WIDTH = 1000;
export const WORLD_HEIGHT = 400;
export const WORLD_LAT_TOP = 84;

/** Longitude/latitude to a point in the viewBox. */
export function project(lon: number, lat: number): { x: number; y: number } {
  return {
    x: ((lon + 180) / 360) * WORLD_WIDTH,
    y: ((WORLD_LAT_TOP - lat) / 360) * WORLD_WIDTH,
  };
}

